from pathlib import Path
from html import escape
root=Path(__file__).resolve().parent
views=['Entrance','Interior','Mirror','Controls','Ceiling','Floor']
figures=''.join(f'<figure><a href="{v}%20After.png"><img loading="lazy" src="{v}%20After.png" alt="{v} view from Unity"></a><figcaption>{v}</figcaption></figure>' for v in views)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Elevator review</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;background:#121512;color:#e0e2d9;font:16px/1.5 system-ui,sans-serif}main{max-width:1500px;padding:32px;margin:auto}h1{font-size:28px;font-weight:500}p{color:#bfc4b6;max-width:950px}a{color:#d2d8b8}figure{margin:0;background:#20251f;border:1px solid #41483b}img{width:100%;display:block}figcaption{padding:10px 14px}section{margin:28px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.compare{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.compare img{height:660px;object-fit:contain;background:#080a08}button{padding:8px 16px;border:1px solid #69735a;background:#2b3326;color:#eee;cursor:pointer;margin-right:8px}select{padding:9px;background:#2b3326;color:#eee;border:1px solid #69735a}@media(max-width:800px){.grid,.compare{grid-template-columns:1fr}.compare img{height:auto}}
</style><main><h1>Elevator interior</h1><p>Actual Unity captures. The supplied concept is a visual reference only; it is not a game texture. Click any image for its original resolution.</p>
<section><select id="view">'''+''.join(f'<option>{v}</option>' for v in views)+'''</select> <button id="reference">Concept comparison</button><button id="before">Before / after</button><div class="compare"><figure><img id="left" src="Concept%20Reference.png"><figcaption id="leftlabel">Original concept</figcaption></figure><figure><img id="right" src="Entrance%20After.png"><figcaption id="rightlabel">Entrance — after</figcaption></figure></div></section><section class="grid">'''+figures+'''</section><p><a href="Runtime%20Checks.txt">Runtime checks</a> · <a href="Visual%20Checks.txt">Visual and placement checks</a> · <a href="Readme.txt">Implementation and asset notes</a> · <a href="Sources.json">CC0 sources</a></p></main><script>
let mode='concept';const v=document.getElementById('view'),left=document.getElementById('left'),right=document.getElementById('right');function update(){right.src=v.value+' After.png';document.getElementById('rightlabel').textContent=v.value+' — after';left.src=mode==='concept'?'Concept Reference.png':v.value+' Before.png';document.getElementById('leftlabel').textContent=mode==='concept'?'Original concept':v.value+' — before';if(mode==='before'&&v.value==='Floor'){left.src='Entrance Before.png';document.getElementById('leftlabel').textContent='Initial cabin before (entrance view)';}}v.onchange=update;document.getElementById('reference').onclick=()=>{mode='concept';update()};document.getElementById('before').onclick=()=>{mode='before';update()};
</script></html>'''
(root/'Gallery.html').write_text(html,encoding='utf8')
print('Saved gallery with all six Unity viewpoints and original-concept / before-after comparison.')
